// src/catalogo-cursos/firma-editorial.ts
var CAMPOS_EDITORIALES = [
  "modalidad",
  "sincronia",
  "horas_publicadas",
  "requisitos_publicados",
  "nivel_entrada",
  "nivel_salida"
];
var FIRMAS = /* @__PURE__ */ new WeakMap();
function hechoEditorial(hecho) {
  return [hecho.valor, hecho.motivo, hecho.unidad, hecho.moneda, hecho.alcance];
}
function identidadEditorial(oferta) {
  return JSON.stringify([oferta.unidad.tipo, oferta.unidad.id]);
}
function valorInmutable(valor) {
  return valor === null || typeof valor !== "object" || Object.isFrozen(valor) && Object.values(valor).every(valorInmutable);
}
function firmaEditorial(oferta) {
  const guardada = FIRMAS.get(oferta);
  if (guardada) {
    return guardada;
  }
  const firma = sha256Hex(
    new TextEncoder().encode(
      jsonCanonico([
        oferta.unidad,
        oferta.proveedor_id,
        oferta.titulo_programa,
        oferta.tipo_unidad,
        oferta.url,
        CAMPOS_EDITORIALES.map((campo) => [campo, hechoEditorial(oferta.hechos[campo])])
      ])
    )
  );
  if (Object.isFrozen(oferta) && Object.isFrozen(oferta.hechos) && valorInmutable(oferta.unidad) && CAMPOS_EDITORIALES.every(
    (campo) => Object.isFrozen(oferta.hechos[campo]) && valorInmutable(oferta.hechos[campo].valor)
  )) {
    FIRMAS.set(oferta, firma);
  }
  return firma;
}

