  const candidatas = dinamicos.filter(
    (r) => r.unidad.id === oferta.unidad.id && r.unidad.programa_id === oferta.unidad.programa_id && r.unidad.tipo === oferta.unidad.tipo && r.titulo === oferta.titulo_programa && r.contenido_sha256 === contenido.sha256 && r.captura_sha256 === contenido.sha256_captura && r.url === contenido.url && oferta.referencias.some((ref) => ref.url === r.url && ref.sha256 === r.captura_sha256)
  );
